package in.recallradar;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException; import java.io.*; import java.math.*; import java.time.*; import java.util.*;
@Service @Transactional class IntakeService { private final IntakeJobRepository jobs; private final IntakeLineRepository lines; private final IngredientRepository ingredients; private final SupplierRepository suppliers; private final LocationRepository locations; private final InventoryService inventory; private final TenantService tenants;
 IntakeService(IntakeJobRepository j,IntakeLineRepository l,IngredientRepository i,SupplierRepository s,LocationRepository loc,InventoryService inv,TenantService t){jobs=j;lines=l;ingredients=i;suppliers=s;locations=loc;inventory=inv;tenants=t;}
 IntakeJobResponse uploadCsv(Membership m,MultipartFile file){ if(file==null||file.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a CSV file to review."); if(!Objects.requireNonNullElse(file.getOriginalFilename(),"").toLowerCase().endsWith(".csv"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only CSV imports are supported at this stage."); var job=jobs.save(new IntakeJob(m.organizationId,m.userId,"CSV",file.getOriginalFilename())); try(var reader=new BufferedReader(new InputStreamReader(file.getInputStream()))){var header=reader.readLine(); if(header==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The CSV file is empty."); var columns=index(header); requireColumns(columns); String row;int number=1; while((row=reader.readLine())!=null){number++;if(row.isBlank())continue;var values=row.split(",",-1);try{String ingredient=value(values,columns,"ingredient");String supplier=value(values,columns,"supplier");String batch=value(values,columns,"batch_number");String unit=value(values,columns,"unit");String location=value(values,columns,"location");BigDecimal quantity=new BigDecimal(value(values,columns,"quantity"));String expiryText=optional(values,columns,"expiry_date");LocalDate expiry=blank(expiryText)?null:LocalDate.parse(expiryText);String issue=matchIssue(m,ingredient,supplier,location);lines.save(new IntakeLine(job.id,number,ingredient,supplier,batch,expiry,quantity,unit,location,issue));}catch(Exception e){lines.save(new IntakeLine(job.id,number,"Unclear line","Unclear supplier","?",null,BigDecimal.ZERO,"?","Unclear location","This line could not be read. Correct the CSV and upload it again."));}} }catch(IOException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The CSV file could not be read.");} return response(job,m); }
 List<IntakeJobResponse> jobs(Membership m){return jobs.findByOrganizationIdOrderByCreatedAtDesc(m.organizationId).stream().map(x->response(x,m)).toList();}
 IntakeJobResponse confirm(Membership m,UUID jobId,ConfirmIntakeRequest request){var job=jobs.findByIdAndOrganizationId(jobId,m.organizationId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Import not found."));for(var id:request.lineIds()){var line=lines.findByIdAndJobId(id,job.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Import line not found."));if(line.status!=IntakeStatus.READY)throw new ResponseStatusException(HttpStatus.CONFLICT,"Every selected line must be matched before confirmation.");var ingredient=ingredients.findByOrganizationIdOrderByName(m.organizationId).stream().filter(x->x.name.equalsIgnoreCase(line.ingredientName)).findFirst().orElseThrow();var supplier=suppliers.findByOrganizationIdOrderByName(m.organizationId).stream().filter(x->x.name.equalsIgnoreCase(line.supplierName)).findFirst().orElseThrow();var location=locations.findByOrganizationIdOrderByName(m.organizationId).stream().filter(x->x.name.equalsIgnoreCase(line.locationName)).findFirst().orElseThrow();var lot=inventory.receive(m,new ReceiveLotRequest(ingredient.id,supplier.id,line.supplierBatchNumber,null,line.expiryDate,location.id,line.quantity,line.unit,"Confirmed from "+job.fileName));line.confirmed(lot.lot().id()==null?null:UUID.fromString(lot.lot().id()));}return response(job,m);}
 private IntakeJobResponse response(IntakeJob job,Membership m){var result=lines.findByJobIdOrderByLineNumber(job.id).stream().map(x->new IntakeLineResponse(x.id.toString(),x.lineNumber,x.ingredientName,x.supplierName,x.supplierBatchNumber,x.expiryDate,x.quantity,x.unit,x.locationName,x.status,x.issue,issues(m,x),x.receiptLotId==null?null:x.receiptLotId.toString())).toList();return new IntakeJobResponse(job.id.toString(),job.fileName,job.status,job.createdAt,result);}
 private String matchIssue(Membership m,String ingredient,String supplier,String location){var issues=new ArrayList<String>();if(ingredients.findByOrganizationIdOrderByName(m.organizationId).stream().noneMatch(x->x.name.equalsIgnoreCase(ingredient)))issues.add("Ingredient is not in your catalogue");if(suppliers.findByOrganizationIdOrderByName(m.organizationId).stream().noneMatch(x->x.name.equalsIgnoreCase(supplier)))issues.add("Supplier is not in your catalogue");if(locations.findByOrganizationIdOrderByName(m.organizationId).stream().noneMatch(x->x.name.equalsIgnoreCase(location)))issues.add("Location is not in your catalogue");return issues.isEmpty()?null:String.join(" · ",issues);}
 IntakeJobResponse resolve(Membership m,UUID jobId,UUID lineId,ResolveIntakeLineRequest request){tenants.requireMasterDataEditor(m);var job=jobs.findByIdAndOrganizationId(jobId,m.organizationId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Import not found."));var line=lines.findByIdAndJobId(lineId,job.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Import line not found."));if(line.status==IntakeStatus.CONFIRMED)throw new ResponseStatusException(HttpStatus.CONFLICT,"A confirmed line cannot be changed.");String field=request.field().trim().toLowerCase(Locale.ROOT);if(field.equals("ingredient")){line.ingredientName=request.create()?tenants.createIngredient(m,new IngredientRequest(line.ingredientName,"Imported",line.unit)).name():ingredients.findByIdAndOrganizationId(requireCandidate(request),m.organizationId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Ingredient not found.")).name;}else if(field.equals("supplier")){line.supplierName=request.create()?tenants.createSupplier(m,new SupplierRequest(line.supplierName,null,null,null)).name():suppliers.findByIdAndOrganizationId(requireCandidate(request),m.organizationId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Supplier not found.")).name;}else if(field.equals("location")){line.locationName=request.create()?tenants.createLocation(m,new LocationRequest(line.locationName,LocationType.WAREHOUSE,"Imported from CSV review")).name():locations.findByIdAndOrganizationId(requireCandidate(request),m.organizationId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Location not found.")).name;}else throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Field must be ingredient, supplier, or location.");line.issue=matchIssue(m,line.ingredientName,line.supplierName,line.locationName);line.status=line.issue==null?IntakeStatus.READY:IntakeStatus.REVIEW;return response(job,m);}
 private UUID requireCandidate(ResolveIntakeLineRequest request){if(request.candidateId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a suggested match or create a new catalogue record.");return request.candidateId();}
 private List<IntakeIssueResponse> issues(Membership m,IntakeLine line){var out=new ArrayList<IntakeIssueResponse>();if(ingredients.findByOrganizationIdOrderByName(m.organizationId).stream().noneMatch(x->x.name.equalsIgnoreCase(line.ingredientName)))out.add(new IntakeIssueResponse("ingredient",line.ingredientName,"Ingredient ‘"+line.ingredientName+"’ is not in your catalogue",ingredientCandidates(m,line.ingredientName)));if(suppliers.findByOrganizationIdOrderByName(m.organizationId).stream().noneMatch(x->x.name.equalsIgnoreCase(line.supplierName)))out.add(new IntakeIssueResponse("supplier",line.supplierName,"Supplier ‘"+line.supplierName+"’ is not in your catalogue",supplierCandidates(m,line.supplierName)));if(locations.findByOrganizationIdOrderByName(m.organizationId).stream().noneMatch(x->x.name.equalsIgnoreCase(line.locationName)))out.add(new IntakeIssueResponse("location",line.locationName,"Location ‘"+line.locationName+"’ is not in your catalogue",locationCandidates(m,line.locationName)));return out;}
 private List<IntakeMatchCandidate> ingredientCandidates(Membership m,String value){return ingredients.findByOrganizationIdOrderByName(m.organizationId).stream().map(x->candidate(x.id,x.name,value)).filter(x->x.confidence()>=45).sorted(Comparator.comparing(IntakeMatchCandidate::confidence).reversed()).limit(3).toList();}private List<IntakeMatchCandidate> supplierCandidates(Membership m,String value){return suppliers.findByOrganizationIdOrderByName(m.organizationId).stream().map(x->candidate(x.id,x.name,value)).filter(x->x.confidence()>=45).sorted(Comparator.comparing(IntakeMatchCandidate::confidence).reversed()).limit(3).toList();}private List<IntakeMatchCandidate> locationCandidates(Membership m,String value){return locations.findByOrganizationIdOrderByName(m.organizationId).stream().map(x->candidate(x.id,x.name,value)).filter(x->x.confidence()>=45).sorted(Comparator.comparing(IntakeMatchCandidate::confidence).reversed()).limit(3).toList();}private IntakeMatchCandidate candidate(UUID id,String name,String target){return new IntakeMatchCandidate(id.toString(),name,similarity(target,name));}private int similarity(String left,String right){var a=left.toLowerCase(Locale.ROOT);var b=right.toLowerCase(Locale.ROOT);int[][] d=new int[a.length()+1][b.length()+1];for(int i=0;i<=a.length();i++)d[i][0]=i;for(int j=0;j<=b.length();j++)d[0][j]=j;for(int i=1;i<=a.length();i++)for(int j=1;j<=b.length();j++)d[i][j]=Math.min(Math.min(d[i-1][j]+1,d[i][j-1]+1),d[i-1][j-1]+(a.charAt(i-1)==b.charAt(j-1)?0:1));int longest=Math.max(a.length(),b.length());return longest==0?100:(int)Math.round(100d*(longest-d[a.length()][b.length()])/longest);}
 private Map<String,Integer> index(String header){var out=new HashMap<String,Integer>();var v=header.replace("\ufeff","").split(",",-1);for(int i=0;i<v.length;i++)out.put(v[i].trim().toLowerCase(),i);return out;}private void requireColumns(Map<String,Integer> c){for(var x:List.of("ingredient","supplier","batch_number","quantity","unit","expiry_date","location"))if(!c.containsKey(x))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"CSV needs the column: "+x); }private String value(String[] row,Map<String,Integer> c,String key){int i=c.get(key);if(i>=row.length||row[i].trim().isEmpty())throw new IllegalArgumentException();return row[i].trim();}private String optional(String[] row,Map<String,Integer> c,String key){int i=c.get(key);return i>=row.length?"":row[i].trim();}private boolean blank(String x){return x==null||x.isBlank();}
}
